private boolean dfs(int node, int target, List<List<Integer>> adj, boolean[] visited) {
    if (node == target) {
        return true;
    }
    visited[node] = true;            // mark BEFORE recursing
    for (int next : adj.get(node)) {
        if (!visited[next]) {
            if (dfs(next, target, adj, visited)) {
                return true;
            }
        }
    }
    return false;
}

