private boolean hasCycle(int node, List<List<Integer>> adj, boolean[] visited, boolean[] recStack) {
    visited[node] = true;
    recStack[node] = true;
    for (int next : adj.get(node)) {
        if (!visited[next]) {
            if (hasCycle(next, adj, visited, recStack)) {
                return true;
            }
        } else if (recStack[next]) {
            return true;             // back-edge to a node still on THIS path
        }
    }
    recStack[node] = false;          // unwind: off the current path
    return false;
}

PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);   // {node, dist}
int[] dist = new int[N];
Arrays.fill(dist, Integer.MAX_VALUE);
dist[src] = 0;
pq.add(new int[]{src, 0});
while (!pq.isEmpty()) {
    int[] cur = pq.poll();
    if (cur[1] > dist[cur[0]]) {
        continue;                    // stale entry, already improved
    }
    for (State e : adj.get(cur[0])) {
        if (dist[cur[0]] + e.weight < dist[e.node]) {
            dist[e.node] = dist[cur[0]] + e.weight;
            pq.add(new int[]{e.node, dist[e.node]});
        }
    }
}

