List<Integer> order = new ArrayList<>();
while (!q.isEmpty()) {
    int node = q.poll();
    order.add(node);
    for (int next : adj.get(node)) {
        indegree[next]--;
        if (indegree[next] == 0) {
            q.add(next);
        }
    }
}
// order.size() < N  =>  the graph has a cycle

Queue<int[]> q = new LinkedList<>();
for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
        if (grid[i][j] == 2) {
            q.add(new int[]{i, j});   // ALL sources before the first poll
        }
    }
}
int time = 0;
while (!q.isEmpty()) {
    int size = q.size();              // freeze the level size
    for (int k = 0; k < size; k++) {
        int[] cell = q.poll();
        for (int[] d : dirs) {
            int x = cell[0] + d[0], y = cell[1] + d[1];
            if (isValid(x, y, n, m) && grid[x][y] == 1) {
                grid[x][y] = 2;
                q.add(new int[]{x, y});
            }
        }
    }
    time++;
}

PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);   // {node, weight}
boolean[] inMst = new boolean[N + 1];
pq.add(new int[]{1, 0});
int total = 0;
while (!pq.isEmpty()) {
    int[] cur = pq.poll();
    if (inMst[cur[0]]) {
        continue;                     // already absorbed
    }
    inMst[cur[0]] = true;
    total += cur[1];
    for (Road r : adj.get(cur[0])) {
        if (!inMst[r.to]) {
            pq.add(new int[]{r.to, r.cost});
        }
    }
}
return total;

private static final int[][] DIRS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

private boolean isValid(int x, int y, int n, int m) {
    return x >= 0 && x < n && y >= 0 && y < m;
}

